Here is the root cause:
The bug is a use-after-free in bond_xmit_broadcast() due to a race condition. The function iterates over the slave list under RCU protection and uses bond_is_last_slave() to determine which slave receives the original skb (zero-copy) versus a clone. However, concurrent slave operations (enslave/release) can mutate the slave list during the loop, causing bond_is_last_slave() to yield inconsistent results (e.g., indicating a non-last slave as last or vice versa). This leads to the original skb being consumed (freed) by the last slave and also being cloned for another slave (which reads freed memory), resulting in a use-after-free crash.

Here is the patch:
  */
 static netdev_tx_t bond_xmit_broadcast(struct sk_buff *skb,
 				       struct net_device *bond_dev,
 				       bool all_slaves)
 {
 	struct bonding *bond = netdev_priv(bond_dev);
 	struct bond_up_slave *slaves;
 	bool xmit_suc = false;
 	bool skb_used = false;
 	int slaves_count, i;

 	if (all_slaves)
 		slaves = rcu_dereference(bond->all_slaves);
 	else
 		slaves = rcu_dereference(bond->usable_slaves);

 	slaves_count = slaves ? READ_ONCE(slaves->count) : 0;
 	for (i = 0; i < slaves_count; i++) {
 		struct slave *slave = slaves->arr[i];
 		struct sk_buff *skb2;

 		if (!(bond_slave_is_up(slave) && slave->link == BOND_LINK_UP))
 			continue;

-		if (bond_is_last_slave(bond, slave)) {
+		if (i + 1 == slaves_count) {
 			skb2 = skb;
 			skb_used = true;
 		} else {
 			skb2 = skb_clone(skb, GFP_ATOMIC);
 			if (!skb2) {
 				net_err_ratelimited("%s: Error: %s: skb_clone() failed\n",
 						    bond_dev->name, __func__);
 				continue;
 			}
 		}

 		if (bond_dev_queue_xmit(bond, skb2, slave->dev) == NETDEV_TX_OK)
 			xmit_suc = true;
 	}

 	if (!skb_used)
 		dev_kfree_skb_any(skb);

 	if (xmit_suc)
 		return NETDEV_TX_OK;

 	dev_core_stats_tx_dropped_inc(bond_dev);
 	return NET_XMIT_DROP;
 }



